findings=[{'id':'guardrails-apt-publication-order','kind':'finding','run':run,'category':'defect','domain':'code','summary':'APT publication exposes new indexes before uploading the package files they name.','scenario':'Release publication uploads dists metadata successfully, then the pool upload fails; the live Packages index advertises the new .deb while that object is absent. Publisher exits nonzero but leaves the repository broken for installs/upgrades until a repair or retry.','evidence':[{'path':'scripts/apt/publish.sh','lines':'41-60','point':'rclone sync of each live dists suite precedes rclone copy of additive pool files.'},{'path':'.github/workflows/package-publish.yml','lines':'161-181','point':'The release job validates the local repository, publishes to R2, and runs live smoke checks only after publication succeeds.'},{'path':'scripts/apt/smoke-test.sh','lines':'44-59','point':'Live smoke checks fetch signed metadata and Package names, not the package payload objects referenced by their Filename fields.'}],'trace':'package-publish APT job -> validate local repository -> publish.sh sync live dists -> pool copy failure -> set -e abort -> new index remains live with absent payload','authority':{'source':'failure-mode; rclone sync command documentation https://rclone.org/commands/rclone_sync/','quote':'A published APT index must only reference package objects available to clients. Separate rclone invocations do not provide a cross-call commit barrier.'},'proof':proof('apt_publication_keeps_live_references_available','probe-apt-publication.py','apt-publication-red.log'),'severity':'Public APT suite availability: normal new-release path, transient upload failure sufficient; all users selecting that version can fail install/upgrade. Also a shorter exposure window on a successful slow pool upload. No artifact corruption or cache data loss established. Boundary fixture models rclone semantics; it does not contact R2 or validate signatures.','status':'open'}]
log=root/'investigation/evidence/verify-timeout-red.log'
